import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"InspectorRow","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/inspector-row.md","filePath":"workbench/inspector-row.md"}'),n={name:"workbench/inspector-row.md"};function d(s,e,i,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="inspectorrow" tabindex="-1">InspectorRow <a class="header-anchor" href="#inspectorrow" aria-label="Permalink to &quot;InspectorRow&quot;">​</a></h1><p>InspectorRow is one setting of an inspector: its name, and the control that changes it or the value it has.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for each setting in an <a href="./inspector-section">InspectorSection</a>, so that the names line up in one column. The application passes the control: a <a href="./../components/text-input">TextInput</a>, a <a href="./../components/number-input">NumberInput</a>, a <a href="./../components/select">Select</a>, or a <a href="./../components/read-value">ReadValue</a> for a value that is only read. Give the control&#39;s id in <code>for</code> so that the name labels it, or an accessible name of its own. For a list of settings described as data, use a <a href="./field-list">FieldList</a>, which draws these rows.</p><p>A switch or a count sits at the end of the row (<code>align=&quot;end&quot;</code>). A <a href="./../components/slider">Slider</a> or a <a href="./../components/toggle">Toggle</a> is a small control: mark the row <code>small</code>, so that it is as tall as the control.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code></td><td>required</td><td>The name</td></tr><tr><td><code>for</code></td><td></td><td>The id of the control that the name labels</td></tr><tr><td><code>hint</code></td><td></td><td>A caption under the value</td></tr><tr><td><code>align</code></td><td><code>start</code></td><td><code>start</code> fills the value column; <code>end</code> keeps its width</td></tr><tr><td><code>small</code></td><td><code>false</code></td><td>The value is a control of a small button&#39;s height</td></tr><tr><td><code>children</code></td><td>required</td><td>The control or the value</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A <a href="./../components/pair">Pair</a>: the name column is 7.5rem wide, muted and trimmed to its ink, gap-sm from the value, and the name is level with the text of the control. The row has the height of a button, or of a small button with <code>small</code>; with a hint it grows, and the hint is a muted caption gap-xs under the value. With <code>start</code> the control fills the value column; with <code>end</code> it keeps its own width at the right end. The row owns the padding at its sides, as a Pair does. Below 24rem the name sits above the value.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/inspector-row/" title="InspectorRow" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/inspector-row/" target="_blank" rel="noopener">InspectorRow</a></figcaption></figure>',11)])])}const u=t(n,[["render",d]]);export{m as __pageData,u as default};
